insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('781f1099-8e9d-4371-b55f-36ff31750bf5', 'ddfe8d60-68eb-401a-b229-03b84ac27dd6', $$functie f(x) = 2x + 1/x voor x > 0$$,
   $$wiskunde-b-vwo-2023-i-een-gebroken-functie-context1.png$$,
   $$De functie f wordt voor x > 0 gegeven door f(x) = 2x + 1/x.$$, 'inline'),
  ('f25f310f-d50a-4030-9772-ff3b142d4b58', 'ddfe8d60-68eb-401a-b229-03b84ac27dd6', $$f heeft een minimum$$,
   $$wiskunde-b-vwo-2023-i-een-gebroken-functie-context2.png$$,
   $$De functie f heeft een minimum.$$, 'inline'),
  ('34f84e88-0a52-4000-878b-29a4b341b880', 'ddfe8d60-68eb-401a-b229-03b84ac27dd6', $$scheve asymptoot k en vlakdeel V tussen x = a en x = 2a (figuur)$$,
   $$wiskunde-b-vwo-2023-i-een-gebroken-functie-context3.png$$,
   $$Lijn k is de scheve asymptoot van de grafiek van f.
Het vlakdeel V wordt ingesloten door de grafiek van f, lijn k en de lijnen met vergelijking x = a en x = 2a met a > 0. In de figuur is dit vlakdeel voor een zekere waarde van a grijsgemaakt.
figuur: de grafiek van f, lijn k en het grijze vlakdeel V tussen x = a en x = 2a$$, 'inline'),
  ('ab17f6e1-f36e-4e1c-b062-0effc21e21b1', 'ddfe8d60-68eb-401a-b229-03b84ac27dd6', $$oppervlakte van V is onafhankelijk van a$$,
   $$wiskunde-b-vwo-2023-i-een-gebroken-functie-context4.png$$,
   $$De oppervlakte van dit vlakdeel is onafhankelijk van de waarde van a.$$, 'inline'),
  ('30650331-7d6d-4e7e-bbd4-e191cc1be3c3', 'ddfe8d60-68eb-401a-b229-03b84ac27dd6', $$vlakdeel W tussen de grafiek van f en de lijn y = 3, gewenteld om y = 3$$,
   $$wiskunde-b-vwo-2023-i-een-gebroken-functie-context5.png$$,
   $$Verder is gegeven de lijn met vergelijking y = 3. Deze lijn en de grafiek van f sluiten een vlakdeel W in dat wordt gewenteld om de lijn met vergelijking y = 3.$$, 'inline'),
  ('2254eb05-d610-48e1-bf6d-443cada37e9f', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$inleiding: vrijbuigen van metalen platen$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context1.png$$,
   $$In de werktuigbouw moeten vaak metalen platen in een bepaalde hoek worden gebogen. Een van de technieken die daarbij worden gebruikt is vrijbuigen. Daarbij ligt de metalen plaat op een matrijs met een bepaalde vorm. Hierna wordt een stempel met kracht op de plaat gedrukt, zodat deze de gewenste vorm krijgt. In figuur 1 is dit in een vooraanzicht weergegeven. In figuur 2 zie je een voorbeeld van een metalen plaat na het buigen.$$, 'inline'),
  ('b06051e6-7d25-47fc-b7a2-b7fbbf9a571f', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$figuur 1 en 2; neutrale lijn en buigen over 45° (cirkelbogen met straal 2d en 3d, P'Q' op 0,4d)$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context2.png$$,
   $$figuur 1: vrijbuigen met stempel, metaal en matrijs; figuur 2: een gebogen metalen plaat
Tijdens het vrijbuigen treedt vervorming op: aan de buitenkant rekt het metaal iets op en aan de binnenkant wordt het samengedrukt. In het inwendige van de metalen plaat bevindt zich de neutrale lijn: de lengte hiervan blijft gelijk na vervorming. In deze opgave nemen we aan dat de dikte van de plaat bij het buigen gelijk blijft.
In figuur 3 is het vooraanzicht van een metalen plaat met een dikte van d mm zowel vóór als na het buigen weergegeven. Wanneer de plaat wordt gebogen over een hoek van 45°, verandert rechthoek ABCD in de vorm A''B''C''D''. Hierbij is boog C''D'' de boog van een cirkel met middelpunt M en straal 2d en A''B'' de boog van een cirkel met middelpunt M en straal 3d. De neutrale lijn P''Q'' is een cirkelboog op een afstand van 0,4d van boog C''D''. Verder geldt dat de lengte van de neutrale lijn gelijk blijft, dus de lengte van boog P''Q'' is gelijk aan de lengte van PQ.$$, 'inline'),
  ('c6a9cc5f-4053-4300-b0de-b1260633e73a', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$figuur 3: plaat ABCD vóór en A'B'C'D' na het buigen$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context3.png$$,
   $$figuur 3: rechthoek ABCD met PQ (dikte d) vóór het buigen en A''B''C''D'' met de neutrale lijn P''Q'' na het buigen (middelpunt M, hoek 45°, MD'' = 2d, D''P'' = 0,4d)$$, 'inline'),
  ('4168cd77-b619-43a7-b3d6-6d353ecf063a', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$benodigde kracht hangt af van metaal, dikte en opening matrijs$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context4.png$$,
   $$De kracht die uitgeoefend moet worden op een metalen plaat om deze te buigen, hangt af van het soort metaal, de dikte van het metaal en de breedte van de opening van de matrijs. De formule om deze kracht uit te rekenen luidt:$$, 'inline'),
  ('a7684d1d-f2ff-475c-8f23-8f0595c95d7b', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$formule 1: F = (R · d²)/V · (1 + 4d/V)$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context5.png$$,
   $$F = (R · d²)/V · (1 + 4d/V) (formule 1)$$, 'inline'),
  ('624d898f-380d-4470-a536-45499198b60a', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$betekenis van F, R, d en V$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context6.png$$,
   $$Hierbij is: − F de benodigde kracht (in kN/m); − R een constante die afhangt van het soort metaal; − d de dikte van het metaal (in mm); − V de breedte van de opening van de matrijs (in mm).$$, 'inline'),
  ('bb90a164-b514-4100-aedd-88a73fc89a14', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$d = 10 mm, V = 200 mm geeft F = 420 kN/m$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context7.png$$,
   $$Voor het buigen van een metalen plaat met een dikte van 10 mm op een matrijs met een opening van 200 mm is een kracht van 420 kN/m nodig. Als je deze metalen plaat zou buigen op een matrijs met een opening van 100 mm is meer kracht nodig.$$, 'inline'),
  ('19b84629-0c0a-4430-a169-479318a343ce', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$formule voor de breedte van de opening van de matrijs$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context8.png$$,
   $$Om bij een gegeven plaatdikte de breedte van de opening van de matrijs te berekenen, wordt de volgende formule gebruikt:$$, 'inline'),
  ('4df8017f-cf41-4821-929c-7d6ef3664b53', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$formule 2: V = d^(1,75); formules 1 en 2 combineren$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context9.png$$,
   $$V = d^(1,75) (formule 2)
Door formule 1 en formule 2 te combineren krijg je een formule die de benodigde kracht F uitdrukt in R en d.$$, 'inline'),
  ('4ff81532-7251-4e74-a82f-57fc3f36c40c', '48200a24-2f81-4f98-aedd-4fe1bcf1923c', $$er is een plaatdikte waarbij F minimaal is$$,
   $$wiskunde-b-vwo-2023-i-buigen-van-metalen-platen-context10.png$$,
   $$Er is een plaatdikte d waarbij de benodigde kracht F minimaal is.$$, 'inline'),
  ('01ed6ef7-b961-4a28-a56f-903b54dfbe16', '18ef711d-7e3a-40a3-901b-14a325284776', $$bewegingsvergelijkingen van punt P$$,
   $$wiskunde-b-vwo-2023-i-gedraaide-parabool-context1.png$$,
   $$De bewegingsvergelijkingen van een punt P worden gegeven door:$$, 'inline'),
  ('2f7de46e-3d1a-4f6f-9d42-07623551c31c', '18ef711d-7e3a-40a3-901b-14a325284776', $$xₚ(t) = 2t, yₚ(t) = 2t²$$,
   $$wiskunde-b-vwo-2023-i-gedraaide-parabool-context2.png$$,
   $$xₚ(t) = 2t
yₚ(t) = 2t²$$, 'inline'),
  ('45f4ce4b-368c-4644-9283-58dc9c85b7ec', '18ef711d-7e3a-40a3-901b-14a325284776', $$M midden van OP, MP⃗ rechtsom 90° geroteerd tot MQ⃗; bewegingsvergelijkingen van Q (figuur 1)$$,
   $$wiskunde-b-vwo-2023-i-gedraaide-parabool-context3.png$$,
   $$Punt M is het midden van lijnstuk OP. Vector MP⃗ wordt rechtsom geroteerd om M over 90°. Zo ontstaat de beeldvector MQ⃗.
In figuur 1 is voor een waarde van t de situatie weergegeven.
Tijdens de beweging van P beschrijft ook het punt Q een baan. In figuur 1 is deze baan gestippeld weergegeven.
De bewegingsvergelijkingen van Q worden gegeven door:
x_Q(t) = t + t²
y_Q(t) = t² − t
figuur 1: de banen van P (parabool) en Q (gestippeld), met M, P en Q voor een waarde van t$$, 'inline'),
  ('88abfd5d-848d-4e77-8c22-06604b193893', '18ef711d-7e3a-40a3-901b-14a325284776', $$snelheid van P is √(4 + 16t²)$$,
   $$wiskunde-b-vwo-2023-i-gedraaide-parabool-context4.png$$,
   $$De snelheid waarmee P beweegt, is gegeven door √(4 + 16t²).$$, 'inline'),
  ('87995ade-41f5-4668-a866-2094bc09e949', '18ef711d-7e3a-40a3-901b-14a325284776', $$snelheid van P is c keer de snelheid van Q$$,
   $$wiskunde-b-vwo-2023-i-gedraaide-parabool-context5.png$$,
   $$Voor elke waarde van t is deze snelheid een factor c keer zo groot als de snelheid van Q.$$, 'inline'),
  ('4033f8d8-b62d-4fc0-8106-99e5065b8915', '18ef711d-7e3a-40a3-901b-14a325284776', $$lengte L = |t| · √(2t² + 2) van PQ met knik in O (figuur 2)$$,
   $$wiskunde-b-vwo-2023-i-gedraaide-parabool-context6.png$$,
   $$Voor elke waarde van t wordt de lengte L van lijnstuk PQ bepaald.
Er geldt:
L = |t| · √(2t² + 2)
In figuur 2 is de grafiek van L weergegeven.
In de oorsprong, bij t = 0, zien we een knik. Als t vanaf links of vanaf rechts tot 0 nadert, nadert de waarde van L in beide situaties ook tot 0. De helling van de grafiek van L nadert echter niet in beide situaties tot dezelfde waarde.
figuur 2: de grafiek van L met een knik in O$$, 'inline'),
  ('c0d2197d-076c-4368-be81-203a6fd66641', 'fd069794-84e7-48b1-a4c0-779d3696ac83', $$functie f(x) = |sin(x) + ½√3|$$,
   $$wiskunde-b-vwo-2023-i-absolute-sinus-context1.png$$,
   $$De functie f wordt gegeven door f(x) = |sin(x) + ½√3|.$$, 'inline'),
  ('fdf48db3-1c77-496a-bb84-1f9fa434fabd', 'fd069794-84e7-48b1-a4c0-779d3696ac83', $$grafiek van f doorgetrokken in de figuur$$,
   $$wiskunde-b-vwo-2023-i-absolute-sinus-context2.png$$,
   $$In de figuur is de grafiek van f als doorgetrokken lijn weergegeven.$$, 'inline'),
  ('268ec746-69f9-433d-9fb8-213657967a15', 'fd069794-84e7-48b1-a4c0-779d3696ac83', $$figuur: grafieken van f en g met toppen A en B$$,
   $$wiskunde-b-vwo-2023-i-absolute-sinus-context3.png$$,
   $$figuur: de grafiek van f (doorgetrokken) en van g (gestippeld) met de toppen A en B en een grijs klein vlakdeel$$, 'inline'),
  ('04b72cc2-6fd3-4f60-add4-3cee6877be97', 'fd069794-84e7-48b1-a4c0-779d3696ac83', $$A en B zijn toppen bij de eerste twee maxima van f rechts van de y-as$$,
   $$wiskunde-b-vwo-2023-i-absolute-sinus-context4.png$$,
   $$In de figuur zijn de toppen A en B van de grafiek van f aangegeven.
A en B zijn de toppen die horen bij de eerste twee maxima van f rechts van de y-as.$$, 'inline'),
  ('4c148035-99f2-4c71-8f28-b46065590fa0', 'fd069794-84e7-48b1-a4c0-779d3696ac83', $$sinusoïde g(x) = a + b·sin(x) met toppen in A en B$$,
   $$wiskunde-b-vwo-2023-i-absolute-sinus-context5.png$$,
   $$Er bestaat een sinusoïde die gegeven wordt door g(x) = a + b·sin(x), waarvan twee opeenvolgende toppen samenvallen met de punten A en B. De grafiek van g is in de figuur gestippeld weergegeven.$$, 'inline'),
  ('dc171479-2010-4ec9-8dcb-c505824de06b', 'fd069794-84e7-48b1-a4c0-779d3696ac83', $$kleine en grote vlakdelen tussen de grafiek van f en de x-as$$,
   $$wiskunde-b-vwo-2023-i-absolute-sinus-context6.png$$,
   $$De grafiek van f en de x-as sluiten twee soorten vlakdelen in: kleine vlakdelen en grote vlakdelen. In de figuur is een van de kleine vlakdelen grijsgemaakt.$$, 'inline'),
  ('eb4e8c6a-8b6e-4b78-a513-ccb3e897537a', '7a66cdc5-0866-40af-a999-de4ed2c91545', $$f(x) = ln(x), g(x) = 1 + e² · (1 − ln(x)); raaklijnen snijden elkaar loodrecht (figuur 1)$$,
   $$wiskunde-b-vwo-2023-i-logaritmische-functies-context1.png$$,
   $$De functie f wordt gegeven door:
f(x) = ln(x)
De functie g wordt gegeven door:
g(x) = 1 + e² · (1 − ln(x))
In figuur 1 zijn de grafieken van f en g weergegeven. De raaklijnen aan de grafieken van f en g snijden elkaar loodrecht in het snijpunt.
figuur 1: de grafieken van f en g$$, 'inline'),
  ('7adee145-0ac2-419c-9057-b3d4d8aef2d1', '7a66cdc5-0866-40af-a999-de4ed2c91545', $$lijn y = q snijdt g in A en f in B met AB = 3 (figuur 2)$$,
   $$wiskunde-b-vwo-2023-i-logaritmische-functies-context2.png$$,
   $$In figuur 2 zijn de grafieken van f en g opnieuw weergegeven.
Ook is voor een waarde van q de lijn met vergelijking y = q weergegeven.
Deze lijn snijdt de grafiek van g in punt A en de grafiek van f in punt B, waarbij punt A links van punt B ligt.
Er geldt dat AB = 3.
figuur 2: de grafieken van f en g en de lijn y = q met de snijpunten A en B$$, 'inline'),
  ('dc9b349c-fcae-4f3e-bce4-96f0c3d21af8', 'ea1650f7-0eac-4f33-8430-8af2b8667f37', $$rechthoek OABC, middens F en E, punt P(0, p), snijpunt D$$,
   $$wiskunde-b-vwo-2023-i-bissectrice-in-een-rechthoek-context1.png$$,
   $$Gegeven is rechthoek OABC met O(0, 0), A(8, 0) en C(0, 4).
De punten F en E zijn de middens van respectievelijk OA en BC. Op de negatieve y-as ligt punt P(0, p). Punt D is het snijpunt van het verlengde van lijnstuk PF en lijnstuk AC. Zie figuur 1.$$, 'inline'),
  ('084702a9-9c9c-418e-96ff-6ba219cc83ed', 'ea1650f7-0eac-4f33-8430-8af2b8667f37', $$figuur 1$$,
   $$wiskunde-b-vwo-2023-i-bissectrice-in-een-rechthoek-context2.png$$,
   $$figuur 1: rechthoek OABC met de punten E, F, D en P$$, 'inline'),
  ('53646fe1-439b-45e1-8214-ab3ec6ca8f20', 'ea1650f7-0eac-4f33-8430-8af2b8667f37', $$lijn EF is bissectrice van hoek PED$$,
   $$wiskunde-b-vwo-2023-i-bissectrice-in-een-rechthoek-context3.png$$,
   $$De lijn door E en F is de bissectrice van hoek PED.$$, 'inline'),
  ('f32abf21-97a3-4896-b194-ccf2db974214', 'ea1650f7-0eac-4f33-8430-8af2b8667f37', $$M(4, 2), cirkel c met middelpunt M door D raakt OA en BC$$,
   $$wiskunde-b-vwo-2023-i-bissectrice-in-een-rechthoek-context4.png$$,
   $$M(4, 2) is het snijpunt van AC en EF. Cirkel c heeft middelpunt M en gaat door D. Afhankelijk van de positie van punt P (en dus van de waarde van p) is de cirkel groter of kleiner. Er is precies één waarde van p waarvoor cirkel c raakt aan OA en BC. In figuur 2 is deze situatie weergegeven.$$, 'inline'),
  ('017a35de-a92f-443f-b3e9-df9c6cc95d6a', 'ea1650f7-0eac-4f33-8430-8af2b8667f37', $$figuur 2: cirkel c raakt OA en BC$$,
   $$wiskunde-b-vwo-2023-i-bissectrice-in-een-rechthoek-context5.png$$,
   $$figuur 2: rechthoek OABC met cirkel c (middelpunt M, door D) die OA en BC raakt$$, 'inline'),
  ('6c4565c6-17f4-4b4f-8d9f-f1512ece628d', '47b8b7e8-b79e-4e98-9a75-42f3b4ce83bc', $$functie f(x) = 1/(eˣ + 1)$$,
   $$wiskunde-b-vwo-2023-i-exponentiele-breuk-context1.png$$,
   $$De functie f wordt gegeven door f(x) = 1/(eˣ + 1).$$, 'inline'),
  ('05d3c5eb-8b3d-400f-87ff-565951a26de7', '47b8b7e8-b79e-4e98-9a75-42f3b4ce83bc', $$grafiek van f heeft twee horizontale asymptoten$$,
   $$wiskunde-b-vwo-2023-i-exponentiele-breuk-context2.png$$,
   $$De grafiek van f heeft twee horizontale asymptoten.$$, 'inline'),
  ('add0b11e-4632-4acf-8b02-c8c4b5315976', '47b8b7e8-b79e-4e98-9a75-42f3b4ce83bc', $$primitieve F(x) = x − ln(eˣ + 1)$$,
   $$wiskunde-b-vwo-2023-i-exponentiele-breuk-context3.png$$,
   $$Een primitieve van f is F(x) = x − ln(eˣ + 1).$$, 'inline'),
  ('f612857d-d1e6-4c8e-a8ab-3e22f23a7be6', '47b8b7e8-b79e-4e98-9a75-42f3b4ce83bc', $$vlakdeel tussen f, x-as, y-as en x = a heeft oppervlakte kleiner dan ln(2)$$,
   $$wiskunde-b-vwo-2023-i-exponentiele-breuk-context4.png$$,
   $$Lijn k heeft vergelijking x = a, met a > 0.
De grafiek van f, de x-as, de y-as en lijn k sluiten een vlakdeel in. De oppervlakte van dit vlakdeel is voor elke waarde van a kleiner dan ln(2).$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('8a609187-3cea-4c72-80a5-566226aca190', 'ddfe8d60-68eb-401a-b229-03b84ac27dd6', 1,
   '[{"domain": "Differentiaal- en integraalrekening", "subdomain": "Afgeleide functies"}, {"domain": "Differentiaal- en integraalrekening", "subdomain": "Technieken voor differentiëren"}]'::jsonb,
   '["minimum", "afgeleide", "extreme waarde", "exact berekenen", "gebroken functie"]'::jsonb,
