   $$wiskunde-b-vwo-2023-i-een-gebroken-functie-vraag1.png$$, $$3p 1 Bereken exact dit minimum.$$, array['781f1099-8e9d-4371-b55f-36ff31750bf5', 'f25f310f-d50a-4030-9772-ff3b142d4b58']::uuid[]),
  ('dd425273-d44f-4830-8c20-52e3e683e67c', 'ddfe8d60-68eb-401a-b229-03b84ac27dd6', 2,
